data class TaskListState(
    val sourceFiltering: Boolean=false,val appliedFilter: TaskQueryFilter=TaskQueryFilter(),
    val scopeEpoch: Int? = null, val searchRevision: Int = 0,
    val business: Int? = null, val items: List<WorkTask> = emptyList(), val total: Int = 0,
    val query: String = "", val status: String? = null, val loading: Boolean = false, val loaded: Boolean = false, val problem: ReadProblem? = null,
    val selectedID: Int? = null, val detail: TaskDetails? = null, val detailLoading: Boolean = false, val detailProblem: ReadProblem? = null
) {
    val partial: Boolean get() = total > items.size
    val statuses: List<String> get() = ((if(sourceFiltering)listOf("open","in_progress","done","cancelled") else emptyList())+items.map { it.status } + listOfNotNull(status,appliedFilter.status)).distinct()
    val visible: List<WorkTask> get() = items.filter { item ->
        (sourceFiltering || status == null || item.status == status) && (query.isBlank() || item.title?.contains(query.trim(), ignoreCase = true) == true)
    }
    val showsEmpty: Boolean get() = loaded && !loading && problem == null && !partial && visible.isEmpty()
}

